# test_envcfg.py

import pytest
from envcfg import load_config
import os
import tomllib


def test_precedence_order():
    defaults = {'a': 1, 'b': 2}
    toml_content = b'a = 3'
    env = {'APP_A': '4'}

    with open('config.toml', 'wb') as f:
        f.write(toml_content)

    config = load_config(defaults, 'config.toml', 'APP_', env)
    assert config == {'a': 4, 'b': 2}

    os.remove('config.toml')

def test_nested_overrides():
    defaults = {'server': {'port': 8080}}
    toml_content = b'[server]\nport = 8081'
    env = {'APP_SERVER__PORT': '8082'}

    with open('config.toml', 'wb') as f:
        f.write(toml_content)

    config = load_config(defaults, 'config.toml', 'APP_', env)
    assert config == {'server': {'port': 8082}}

    os.remove('config.toml')

def test_coercion_types():
    defaults = {'a': 1, 'b': 2.0, 'c': True}
    env = {'APP_A': '2', 'APP_B': '3.0', 'APP_C': 'false'}

    config = load_config(defaults, env_prefix='APP_', env=env)
    assert config == {'a': 2, 'b': 3.0, 'c': False}

def test_error_cases():
    defaults = {'a': 1, 'b': 2.0, 'c': True}
    env = {'APP_A': 'two', 'APP_B': 'three', 'APP_C': 'yes'}

    with pytest.raises(Exception) as excinfo:
        load_config(defaults, env_prefix='APP_', env=env)
    assert 'Cannot coerce two to int' in str(excinfo.value)
    assert 'Cannot coerce three to float' in str(excinfo.value)
    assert 'Cannot coerce yes to bool' in str(excinfo.value)

def test_missing_file():
    defaults = {'a': 1}

    config = load_config(defaults)
    assert config == {'a': 1}

